'use strict';
/* The newer Lexicon Saga text (the 3×3 world, the keys and Castle Unwritten, the harbor towns, the royal castles,
   jails, pickpockets, colored chests and treasure selling) for the Spanish, French and Japanese phrase books. Loaded after gametr-ja.js. */
Object.assign(GT_BOOKS.es.names, {"Brother Ansel":"Hermano Ansel","Sister Imane":"Hermana Imane","Mother Solenne":"Madre Solenne","Brother Tobiah":"Hermano Tobiah","Old Hob":"Viejo Hob","Father Edric":"Padre Edric","Sister Ama":"Hermana Ama","Brother Kaveh":"Hermano Kaveh","Captain Nell":"Capitana Nell","Mother Liane":"Madre Liane","Brother Rafi":"Hermano Rafi","Sister Moira":"Hermana Moira","Father Aksel":"Padre Aksel","Mother Iris":"Madre Iris","Brother Cael":"Hermano Cael","Sister Wynne":"Hermana Wynne","Father Lumen":"Padre Lumen","Frostmark Tundra":"Tundra de Frostmark","Wandering priest":"Sacerdote errante","Thundercrag Highlands":"Tierras Altas de Thundercrag","Inkblight Wastes":"Páramos de Inkblight","Verdant Wilds":"Tierras Salvajes Verdes","Mirefen Marsh":"Pantano de Mirefen","Sunscorch Canyon":"Cañón Abrasador","Mother Frida":"Madre Frida","Brother Hale":"Hermano Hale","Father Grey":"Padre Grey","Sister Ivy":"Hermana Ivy","Brother Moss":"Hermano Moss","Mother Sol":"Madre Sol","Castle Unwritten · Hall of Flames":"Castillo Inescrito · Salón de las Llamas","Castle Unwritten · Hall of Hours":"Castillo Inescrito · Salón de las Horas","Castle Unwritten · Hall of Voices":"Castillo Inescrito · Salón de las Voces","Castle Unwritten":"Castillo Inescrito","Merchant":"Mercader","Sea trader":"Comerciante del mar","Harbor priest":"Sacerdote del puerto","Salty Brin":"Brin el Salado","Salty Fros":"Fros el Salado","Salty Palm":"Palm el Salado","Salty Tide":"Tide el Salado","Far Northwest Sea":"Mar del Lejano Noroeste","Frozen Sea":"Mar Helado","Northern Sea":"Mar del Norte","Ink Sea":"Mar de Tinta","Far Northeast Sea":"Mar del Lejano Noreste","Frostwater Sea":"Mar de Aguas Heladas","Blackwater Sea":"Mar de Aguas Negras","Western Sea":"Mar del Oeste","Eastern Ocean":"Océano del Este","Jungle Sea":"Mar de la Selva","Sunset Sea":"Mar del Ocaso","Far Southwest Sea":"Mar del Lejano Suroeste","Coral Sea":"Mar de Coral","Southern Sea":"Mar del Sur","Ember Sea":"Mar de Brasas","Far Southeast Sea":"Mar del Lejano Sureste","Castle Quillhaven":"Castillo de Quillhaven","Queen Maren":"Reina Maren","Royal guard":"Guardia real","Prince Edwin":"Príncipe Edwin","Librarian Ottilie":"Bibliotecaria Ottilie","Page boy":"Paje","Cook Barnaby":"Cocinero Barnaby","Kitchen maid":"Moza de cocina","Off-duty guard":"Guardia de descanso","Captain Hale":"Capitán Hale","Princess Rosalind":"Princesa Rosalind","Lady’s maid":"Doncella","Chancellor Voss":"Canciller Voss","Lady Abigail":"Dama Abigail","Treasury guard":"Guardia del tesoro","Castle maid":"Criada del castillo","Gate guard":"Guardia de la puerta","Lumen Palace":"Palacio Lumen","Prince Tariq":"Príncipe Tariq","Palace guard":"Guardia de palacio","Map keeper Idris":"Cartógrafo Idris","Scholar":"Erudita","Cook Samira":"Cocinera Samira","Captain Zara":"Capitana Zara","Princess Leila":"Princesa Leila","Vizier Omar":"Visir Omar","Ambassador Lys":"Embajadora Lys","Palace maid":"Criada de palacio","Jailer":"Carcelero","Prisoner":"Prisionero","Old prisoner":"Viejo prisionero","Townsperson":"Vecino","Sea glass":"Vidrio marino","Conch shell":"Caracola","Silver ring":"Anillo de plata","Pearl":"Perla","Coral idol":"Ídolo de coral","Gold doubloons":"Doblones de oro","Sunken crown":"Corona hundida","Star sapphire":"Zafiro estrella","Frost Wolf":"Lobo de escarcha","Snow Owl":"Búho nival","Ice Crab":"Cangrejo de hielo","Frost Moth":"Polilla de escarcha","Ice Golem":"Gólem de hielo","Crag Rat":"Rata de los riscos","Thunder Hawk":"Halcón del trueno","Storm Imp":"Diablillo de tormenta","Iron Beetle":"Escarabajo de hierro","Boulder Brute":"Bruto de roca","Ink Ooze":"Lodo de tinta","Blight Wraith":"Espectro marchito","Rot Bat":"Murciélago podrido","Hollow Knight":"Caballero hueco","Cursed Grimoire":"Grimorio maldito","Vine Serpent":"Serpiente de lianas","Jungle Toadstool":"Seta de la selva","Thorn Sprite":"Duende espino","Jungle Parrot":"Loro de la selva","Jade Beetle":"Escarabajo de jade","Bog Blob":"Masa del pantano","Rot Cap":"Hongo podrido","Swamp Eel":"Anguila del pantano","Mud Crab":"Cangrejo de barro","Marsh Moth":"Polilla del pantano","Dust Coyote":"Coyote de polvo","Saguaro Brute":"Bruto saguaro","Canyon Vulture":"Buitre del cañón","Mesa Golem":"Gólem de la meseta","Sun Scarab":"Escarabajo del sol","The Glacier Wyrm":"El Dragón Glaciar","The Storm Roc":"El Roc de la Tormenta","The Lich Scribe":"El Escriba Liche","The Vine Hydra":"La Hidra de Lianas","The Mire Queen":"La Reina del Fango","The Canyon Wyvern":"El Guiverno del Cañón","The Silent Herald":"El Heraldo Silente","Ink Sentinel":"Centinela de tinta","Hoarfrost Cavern":"Caverna de Escarcha","Thunder Mine":"Mina del Trueno","Blighted Crypt":"Cripta Marchita","Overgrown Temple":"Templo Cubierto","Drowned Barrow":"Túmulo Ahogado","Echo Canyon Caves":"Cuevas del Cañón del Eco","Ruby Key":"Llave de Rubí","Sapphire Key":"Llave de Zafiro","Emerald Key":"Llave de Esmeralda","Dawn Quill":"Pluma del Alba","Dusk Inkwell":"Tintero del Ocaso","Star Seal":"Sello Estelar","Statue of Dawn":"Estatua del Alba","Statue of Noon":"Estatua del Mediodía","Statue of Dusk":"Estatua del Ocaso"});
Object.assign(GT_BOOKS.es.lines, {
  "Through the doors, a throne of black ink. The air goes perfectly still. Not a sound. Not even your own steps.": "Tras las puertas, un trono de tinta negra. El aire se queda totalmente quieto. Ni un sonido. Ni siquiera tus pasos.",
  "A tall figure in a robe of blank pages rises from it. Where his words should be, there is only ink.": "Una figura alta con una túnica de páginas en blanco se levanta. Donde deberían estar sus palabras, solo hay tinta.",
  "{p}: You found my keys. You solved my riddles. How tiresome.": "{p}: Encontraste mis llaves. Resolviste mis acertijos. Qué pesadez.",
  "{p}: Words. Noisy, messy, endless words. I will unwrite you first.": "{p}: Palabras. Ruidosas, desordenadas, interminables. Primero te desescribiré a ti.",
  "💎 The {p}’s voice bursts out of the Unwriter’s throne, and the shards begin to sing.": "💎 La voz del {p} sale disparada del trono del Desescritor, y los fragmentos empiezan a cantar.",
  "At the top of the tower, a knight in black armor stands perfectly still.": "En lo alto de la torre, un caballero de armadura negra está totalmente quieto.",
  "He has no mouth. When he speaks, the words appear in the air like smoke.": "No tiene boca. Cuando habla, las palabras aparecen en el aire como humo.",
  "{p}: My master is not here. But his shards are. And I will keep them.": "{p}: Mi amo no está aquí. Pero sus fragmentos sí. Y yo los guardaré.",
  "The Herald’s armor falls apart, empty. A last smoky word drifts away: “castle”.": "La armadura del Heraldo se desmorona, vacía. Una última palabra de humo se aleja: “castillo”.",
  "Behind him, the shards of the {p} glow on a stone table.": "Detrás de él, los fragmentos del {p} brillan sobre una mesa de piedra.",
  "💎 You found the <b>last {p} Shards</b>! Every shard is together at last, but they are silent.": "💎 ¡Encontraste los <b>últimos fragmentos del {p}</b>! Por fin están todos juntos, pero están en silencio.",
  "{p} has hidden away the {p}’s voice.": "{p} ha escondido la voz del {p}.",
  "Take the shards home to {p} in {p}, {p}.": "Lleva los fragmentos a {p} en {p}, {p}.",
  "{p}: {p}… all the shards. I never dreamed I would see the whole {p} again.": "{p}: {p}… todos los fragmentos. Nunca soñé con volver a ver el {p} entero.",
  "But listen: it does not sing. {p} has locked its voice away in <b>Castle Unwritten</b>, in the {p} far to the north-east.": "Pero escucha: no canta. {p} ha encerrado su voz en el <b>Castillo Inescrito</b>, en {p}, muy al noreste.",
  "The castle gate opens only for three keys, hidden long ago at the edges of the world:": "La puerta del castillo solo se abre con tres llaves, escondidas hace mucho en los confines del mundo:",
  "🪶 the <b>Dawn Quill</b>, high in the {p} in the north,": "🪶 la <b>Pluma del Alba</b>, en lo alto de {p}, en el norte,",
  "🫙 the <b>Dusk Inkwell</b>, lost in the {p} in the south,": "🫙 el <b>Tintero del Ocaso</b>, perdido en {p}, en el sur,",
  "⭐ and the <b>Star Seal</b>, fallen into the {p} in the far south.": "⭐ y el <b>Sello Estelar</b>, caído en {p}, en el extremo sur.",
  "I have ordered the old roads opened: north and south of Aldermere, north and south of Seravel. Your ship can sail north and south from the Eastern Isles too.": "He ordenado abrir los caminos antiguos: al norte y al sur de Aldermere, al norte y al sur de Seravel. Tu barco también puede navegar al norte y al sur desde las Islas del Este.",
  "Ask in the taverns. People remember more than they think. Go, and bring back our words!": "Pregunta en las tabernas. La gente recuerda más de lo que cree. ¡Ve y trae de vuelta nuestras palabras!",
  "{p}: All three keys! Castle Unwritten is in the {p}, far to the north-east. End this, hero.": "{p}: ¡Las tres llaves! El Castillo Inescrito está en {p}, muy al noreste. Acaba con esto, héroe.",
  "✨ Something glints between the rocks… you dig it out.": "✨ Algo brilla entre las rocas… lo desentierras.",
  "🪶 You found the <b>Dawn Quill</b>! A golden quill that writes light. (Key {n} of {n})": "🪶 ¡Encontraste la <b>Pluma del Alba</b>! Una pluma dorada que escribe luz. (Llave {n} de {n})",
  "✨ Deep in the trees, a little pool of shadow… no, an inkwell, sitting on a mossy stone.": "✨ En lo hondo del bosque, un charquito de sombra… no, un tintero, sobre una piedra con musgo.",
  "🫙 You found the <b>Dusk Inkwell</b>! Its ink is the color of the evening sky. (Key {n} of {n})": "🫙 ¡Encontraste el <b>Tintero del Ocaso</b>! Su tinta es del color del cielo al atardecer. (Llave {n} de {n})",
  "✨ Something in the dust of the gully twinkles like a fallen star.": "✨ Algo en el polvo del barranco centellea como una estrella caída.",
  "⭐ You found the <b>Star Seal</b>! A silver seal shaped like a star. (Key {n} of {n})": "⭐ ¡Encontraste el <b>Sello Estelar</b>! Un sello de plata con forma de estrella. (Llave {n} de {n})",
  "🔑 The quill, the inkwell and the star hum together in your bag.": "🔑 La pluma, el tintero y la estrella zumban juntos en tu bolsa.",
  "Castle Unwritten’s gate will open for you now. It stands in the {p}, in the far north-east.": "La puerta del Castillo Inescrito se abrirá para ti. Está en {p}, en el extremo noreste.",
  "The cave floor is a frozen lake. Under the ice, two cold eyes open.": "El suelo de la cueva es un lago helado. Bajo el hielo, se abren dos ojos fríos.",
  "A wyrm of ice smashes up through the floor!": "¡Un dragón de hielo rompe el suelo y sale!",
  "{p} shatters into a thousand glittering pieces.": "{p} se hace añicos en mil pedazos brillantes.",
  "Wind howls up the shaft. A giant bird made of storm clouds lands in front of you.": "El viento aúlla por el pozo. Un pájaro gigante hecho de nubes de tormenta se posa delante de ti.",
  "{p}: SKREEEEE!": "{p}: ¡SKRIIIIIII!",
  "{p} dissolves into a harmless spring rain.": "{p} se deshace en una inofensiva lluvia de primavera.",
  "A skeleton in a scholar’s robe looks up from a book of black pages.": "Un esqueleto con túnica de sabio levanta la vista de un libro de páginas negras.",
  "{p}: Ah, visitors. Let me write you… an ending.": "{p}: Ah, visitas. Dejad que os escriba… un final.",
  "{p}’s book slams shut, and he crumbles to dust with it.": "El libro de {p} se cierra de golpe, y él se convierte en polvo con él.",
  "The temple floor cracks. Vines as thick as trees rise up, each with a snapping head.": "El suelo del templo se agrieta. Se alzan lianas gruesas como árboles, cada una con una cabeza que muerde.",
  "{p} hisses from three mouths at once!": "¡{p} sisea por tres bocas a la vez!",
  "{p} withers and sinks back into the ground.": "{p} se marchita y se hunde en la tierra.",
  "The water in the barrow bubbles. A huge shape of mud and weeds rises, wearing a crown of reeds.": "El agua del túmulo burbujea. Se alza una enorme figura de barro y algas con una corona de juncos.",
  "{p}: You are tracking mud into my palace!": "{p}: ¡Me estás llenando el palacio de barro!",
  "{p} slumps back into a harmless puddle. Her crown floats away.": "{p} se derrumba en un charco inofensivo. Su corona se aleja flotando.",
  "Hot wind fills the cave. A red wyvern drops from the ceiling, wings spread wide.": "Un viento caliente llena la cueva. Un guiverno rojo cae del techo con las alas abiertas.",
  "{p} roars, and the whole canyon roars with it!": "¡{p} ruge, y todo el cañón ruge con él!",
  "{p} flees out of a crack in the rock, never to return.": "{p} huye por una grieta de la roca y no vuelve jamás.",
  "💰 {p} guarded a pile of treasure!": "💰 ¡{p} guardaba un montón de tesoros!",
  "💰 {p}’s nest is full of shiny things!": "💰 ¡El nido de {p} está lleno de cosas brillantes!",
  "💰 {p}’s hoard is yours!": "💰 ¡El tesoro de {p} es tuyo!",
  "💰 Treasure hidden among the roots!": "💰 ¡Un tesoro escondido entre las raíces!",
  "💰 {p}’s treasure, a little muddy.": "💰 El tesoro de {p}, un poco embarrado.",
  "💰 The wyvern’s hoard glitters in the dark!": "💰 ¡El tesoro del guiverno brilla en la oscuridad!",
  "The three keys rise out of your bag and fit into the sockets.": "Las tres llaves salen de tu bolsa y encajan en los huecos.",
  "With a sound like a book opening, Castle Unwritten’s gate swings wide.": "Con un ruido como el de un libro que se abre, la puerta del Castillo Inescrito se abre de par en par.",
  "You pull the {p} lever. Its flame goes out.": "Bajas la palanca de {p}. Su llama se apaga.",
  "🔥 Sun, star… and the moon asleep. The iron gate grinds upward!": "🔥 Sol, estrella… y la luna dormida. ¡La reja de hierro sube chirriando!",
  "✨ The plate glows.": "✨ La losa brilla.",
  "The plates sink back into the floor with a groan.": "Las losas vuelven a hundirse en el suelo con un gruñido.",
  "Read the poem again: in what order does the night pass?": "Lee otra vez el poema: ¿en qué orden pasa la noche?",
  "🔥 All four plates blaze with light. The iron gate grinds upward!": "🔥 Las cuatro losas arden de luz. ¡La reja de hierro sube chirriando!",
  "🗿 {p}: “Answer my word, traveler.”": "🗿 {p}: “Responde mi palabra, viajero.”",
  "🗿 {p}: “True words.” Its eyes glow gold.": "🗿 {p}: “Palabras verdaderas.” Sus ojos brillan dorados.",
  "🗿 {p}: “Not true. Come back when you know.”": "🗿 {p}: “No es verdad. Vuelve cuando lo sepas.”",
  "🗿 All three statues glow. The great doors to the throne room swing open!": "🗿 Las tres estatuas brillan. ¡Las grandes puertas de la sala del trono se abren!",
  "Welcome to {p}. The King awaits brave souls.": "Bienvenido a {p}. El Rey espera almas valientes.",
  "{p}’s last guards block the stairs!": "¡Los últimos guardias de {p} bloquean la escalera!",
  "Keep warm! The {p} Wolves hunt in packs out on the tundra.": "¡Abrígate! Los lobos de {p} cazan en manada por la tundra.",
  "East of here the land turns to rock and thunder: the {p}.": "Al este, la tierra se vuelve roca y trueno: {p}.",
  "I built a snow knight yesterday. It has a sword made of an icicle!": "Ayer hice un caballero de nieve. ¡Tiene una espada de carámbano!",
  "Thunder Hawks steal our hats. Every. Single. Day.": "Los halcones del trueno nos roban los sombreros. Todos. Los. Días.",
  "Further east the land goes black. Nothing grows in the {p}.": "Más al este, la tierra se vuelve negra. Nada crece en {p}.",
  "The mine’s gold paid for this town. Now monsters dig there instead.": "El oro de la mina pagó este pueblo. Ahora son los monstruos los que cavan allí.",
  "We are the last town before the castle. Buy {p}: the wraiths out there love curses.": "Somos el último pueblo antes del castillo. Compra {p}: a los espectros de ahí fuera les encantan las maldiciones.",
  "The Blighted Crypt is north-west of here. A Lich Scribe writes death verses down there.": "La Cripta Marchita está al noroeste. Allí abajo un Escriba Liche escribe versos de muerte.",
  "Mum says not to look at the castle at night. I looked. It looked back.": "Mamá dice que no mire el castillo de noche. Lo miré. Me devolvió la mirada.",
  "Vine Serpents bite. Carry Antidotes, always.": "Las serpientes de lianas muerden. Lleva antídotos, siempre.",
  "North is Aldermere. East is the {p}. Mind your boots.": "Al norte está Aldermere. Al este, {p}. Cuidado con las botas.",
  "A parrot taught me a rude word. I won’t say it.": "Un loro me enseñó una palabrota. No la voy a decir.",
  "Rot Caps puff poison. Hold your breath. Or just bring Antidotes.": "Los hongos podridos sueltan veneno. Aguanta la respiración. O mejor, lleva antídotos.",
  "The road north goes back up to Seravel, through the canyon road.": "El camino del norte vuelve a Seravel por la ruta del cañón.",
  "I caught a frog the size of my head! Then it caught me.": "¡Atrapé una rana del tamaño de mi cabeza! Luego ella me atrapó a mí.",
  "The sea north of here leads back to the Eastern Isles, if you have a boat.": "El mar al norte de aquí vuelve a las Islas del Este, si tienes barco.",
  "Sun Scarabs flash so bright you can’t see. Squint!": "Los escarabajos del sol brillan tanto que no se ve nada. ¡Entorna los ojos!",
  "Yell in the canyon and it yells back. I yelled my name forty times.": "Grita en el cañón y te devuelve el grito. Grité mi nombre cuarenta veces.",
  "The way ahead is guarded!": "¡El camino está vigilado!",
  "The Hoarfrost Cavern is north-east of town. Something huge sleeps in the ice down there.": "La Caverna de Escarcha está al noreste del pueblo. Algo enorme duerme en el hielo allí abajo.",
  "The old road south goes back to Aldermere. The King opened it for you, they say.": "El camino viejo del sur vuelve a Aldermere. Dicen que el Rey lo abrió para ti.",
  "Pray, rest, and be brave. {p} fears words spoken with courage.": "Reza, descansa y sé valiente. {p} teme las palabras dichas con valor.",
  "The Dawn Quill? A shepherd swore she saw a golden glint on the peak above the old mine, in the north-west.": "¿La Pluma del Alba? Una pastora juró ver un destello dorado en la cumbre sobre la vieja mina, al noroeste.",
  "The Thunder Mine runs deep. A Storm Roc nests at the bottom.": "La Mina del Trueno es muy profunda. En el fondo anida un Roc de la Tormenta.",
  "Castle Unwritten is east of town. Its gate has three sockets: a quill, an inkwell and a star.": "El Castillo Inescrito está al este del pueblo. Su puerta tiene tres huecos: una pluma, un tintero y una estrella.",
  "Inside the castle, the old guards say, the doors only open for the clever. Levers, plates and talking statues.": "Dentro del castillo, dicen los viejos guardias, las puertas solo se abren a los listos. Palancas, losas y estatuas que hablan.",
  "The Dusk Inkwell? Old Ma {p} talks about a grove nobody can find, deep in the trees in the south-east.": "¿El Tintero del Ocaso? La vieja Ma {p} habla de una arboleda que nadie encuentra, en lo hondo del bosque, al sureste.",
  "The Overgrown Temple is north-east. A Vine Hydra grew out of the floor in there!": "El Templo Cubierto está al noreste. ¡Allí dentro una Hidra de Lianas salió del suelo!",
  "The Drowned Barrow is south-west of town, past the reeds. {p} rules it.": "El Túmulo Ahogado está al suroeste del pueblo, pasados los juncos. Allí manda {p}.",
  "The canyon east of here is dry as bone. Opposite of here, really.": "El cañón al este de aquí está seco como un hueso. Justo lo contrario que aquí.",
  "The Star Seal? There’s a gully in the far west, past the red cliffs, where the stars fall at night.": "¿El Sello Estelar? Hay un barranco en el extremo oeste, pasados los acantilados rojos, donde caen las estrellas de noche.",
  "The Echo Canyon Caves are south-east. A Canyon Wyvern roosts at the bottom.": "Las Cuevas del Cañón del Eco están al sureste. En el fondo anida un Guiverno del Cañón.",
  "🪨 Words are carved into the stone:": "🪨 Hay palabras talladas en la piedra:",
  "“Wake the Sun and the Star, but let the Moon sleep.”": "“Despierta al Sol y a la Estrella, pero deja dormir a la Luna.”",
  "“Beware: every lever stirs the one beside it.”": "“Cuidado: cada palanca mueve la de al lado.”",
  "Two Ink Sentinels step out of the shadows!": "¡Dos centinelas de tinta salen de las sombras!",
  "🪨 A poem is carved into the stone:": "🪨 Hay un poema tallado en la piedra:",
  "“First the quill writes the dawn, then the sun climbs high,”": "“Primero la pluma escribe el alba, luego el sol sube alto,”",
  "“the moon follows after, and a star closes the sky.”": "“la luna lo sigue, y una estrella cierra el cielo.”",
  "Four plates are set into the floor: 🪶 ☀️ 🌙 ⭐": "Hay cuatro losas en el suelo: 🪶 ☀️ 🌙 ⭐",
  "The Statue of Dawn": "La Estatua del Alba",
  "The Statue of Noon": "La Estatua del Mediodía",
  "The Statue of Dusk": "La Estatua del Ocaso",
  "🪨 “Speak true words to the three statues, and the last door will open.”": "🪨 “Di palabras verdaderas a las tres estatuas y se abrirá la última puerta.”",
  "{p}: Rare goods from across the sea! Take a look.": "{p}: ¡Productos raros del otro lado del mar! Echa un vistazo.",
  "{p}: Blades and bows from faraway smithies!": "{p}: ¡Espadas y arcos de herrerías lejanas!",
  "Welcome to {p}, the west harbor of Aldermere! Ships come and go all day.": "¡Bienvenido a {p}, el puerto del oeste de Aldermere! Los barcos van y vienen todo el día.",
  "Sail north along the coast and you reach the {p}. South takes you to the jungle.": "Navega al norte por la costa y llegarás a {p}. Al sur, a la selva.",
  "There’s a shrine on a little island just south of here. Sailors pray there before a long trip.": "Hay un santuario en una islita justo al sur. Los marineros rezan allí antes de un viaje largo.",
  "{p} never freezes. The sea keeps moving, so the ice can’t catch it.": "{p} nunca se congela. El mar no para de moverse, así que el hielo no lo atrapa.",
  "East along the north coast is the Thundercrag shore, and past that, the black Inkblight sea.": "Al este por la costa norte está la orilla de Thundercrag y, más allá, el mar negro de Inkblight.",
  "An island shrine sits just off the coast, north of here. Ice all around it, but warm inside.": "Hay un santuario en una isla junto a la costa, al norte. Hielo por todas partes, pero dentro hace calor.",
  "{p}! Best fish on the whole continent. Don’t tell the Marsh folk I said that.": "¡{p}! El mejor pescado del continente. No le digas a la gente del pantano que lo dije.",
  "You can sail up the river from here, right into the heart of the jungle.": "Desde aquí puedes remontar el río en barco hasta el corazón de la selva.",
  "East along the coast is {p}, then the red canyon. The whole south shore is one long sea road.": "Al este por la costa está {p} y luego el cañón rojo. Toda la costa sur es un largo camino de mar.",
  "{p} sits where the marsh meets the sea. Mind the eels at low tide.": "{p} está donde el pantano se junta con el mar. Cuidado con las anguilas en la marea baja.",
  "The sea lanes go all the way round the continent now that the King opened them.": "Las rutas marítimas dan la vuelta a todo el continente ahora que el Rey las abrió.",
  "Old story: there’s a shrine out on the water, east of here, that heals even the fallen.": "Una vieja historia: hay un santuario sobre el agua, al este de aquí, que cura incluso a los caídos.",
  "Every coast of the continent is linked by sea now. Sail all the way round if you like!": "Todas las costas del continente están unidas por mar. ¡Da la vuelta entera si quieres!",
  "Island shrines heal the whole crew. Steer close and pray from the deck.": "Los santuarios de las islas curan a toda la tripulación. Acércate y reza desde la cubierta.",
  "I pray here before every voyage. The sea is kinder to the faithful.": "Rezo aquí antes de cada viaje. El mar es más amable con los fieles.",
  "{p}: Welcome to our home, young hero. Do look around. The library is my favourite room.": "{p}: Bienvenido a nuestra casa, joven héroe. Mira todo lo que quieras. La biblioteca es mi sala favorita.",
  "{p}: The cook makes the best honey bread in the kingdom. Tell him I sent you.": "{p}: El cocinero hace el mejor pan de miel del reino. Dile que vas de mi parte.",
  "{p}: Stand tall before the King!": "{p}: ¡Ponte derecho ante el Rey!",
  "{p}: Nobody gets near the thrones without our say-so.": "{p}: Nadie se acerca a los tronos sin nuestro permiso.",
  "{p}: One day I’ll go on an adventure too! Father says I must learn my words first.": "{p}: ¡Algún día yo también tendré una aventura! Papá dice que antes tengo que aprender mis palabras.",
  "{p}: Did you know there are chests in three colors? Ruby, sapphire and emerald. Each needs its own key.": "{p}: ¿Sabías que hay cofres de tres colores? Rubí, zafiro y esmeralda. Cada uno necesita su propia llave.",
  "{p}: Shh! This is the royal library. Every book here was written with the old {p}.": "{p}: ¡Chis! Esta es la biblioteca real. Cada libro de aquí se escribió con el viejo {p}.",
  "{p}: Read a little every day and the words will stay with you.": "{p}: Lee un poco cada día y las palabras se quedarán contigo.",
  "{p}: I’m supposed to be dusting the shelves… but this book about sea monsters is really good.": "{p}: Se supone que tengo que quitar el polvo de los estantes… pero este libro de monstruos marinos es buenísimo.",
  "{p}: Mind the hot stove! Honey bread for the King, stew for the guards.": "{p}: ¡Cuidado con el fogón! Pan de miel para el Rey, guiso para los guardias.",
  "{p}: Hungry? Inns are the place for a hot meal and a warm bed.": "{p}: ¿Hambre? Las posadas son el sitio para una comida caliente y una buena cama.",
  "{p}: Twelve loaves, six pies and a cake for the Prince. And the day has only started!": "{p}: Doce hogazas, seis tartas y un pastel para el Príncipe. ¡Y el día acaba de empezar!",
  "{p}: Night shift tonight. I’m resting my feet while I can.": "{p}: Esta noche me toca guardia. Descanso los pies mientras puedo.",
  "{p}: My guards keep the towns safe. If you see a pickpocket, call for us!": "{p}: Mis guardias protegen los pueblos. Si ves a un carterista, ¡llámanos!",
  "{p}: Every town has a jail now. Thieves spend a night behind bars, or pay a fine.": "{p}: Ahora cada pueblo tiene cárcel. Los ladrones pasan una noche entre rejas o pagan una multa.",
  "{p}: Father keeps the Ruby Key in the treasury, downstairs on this side.": "{p}: Papá guarda la Llave de Rubí en la tesorería, abajo, en este lado.",
  "{p}: {p} of Seravel keeps the Sapphire Key. And the Emerald Key? Lost at sea, somewhere far to the south-east.": "{p}: {p} de Seravel guarda la Llave de Zafiro. ¿Y la Llave de Esmeralda? Perdida en el mar, en algún lugar lejos al sureste.",
  "{p}: The Princess’s room must be spotless. She notices every speck of dust!": "{p}: La habitación de la Princesa tiene que estar impecable. ¡Ve cada mota de polvo!",
  "{p}: The royal dinner is at sundown. Forty guests, sixty candles.": "{p}: La cena real es al atardecer. Cuarenta invitados, sesenta velas.",
  "{p}: Taxes, letters, maps… a chancellor’s work is never done.": "{p}: Impuestos, cartas, mapas… el trabajo de un canciller nunca termina.",
  "{p}: I came all the way from {p} for the feast. Isn’t the hall lovely?": "{p}: Vine desde {p} solo para el banquete. ¿No es precioso el salón?",
  "{p}: The King says you may open the treasury chests. The Ruby Key is in the locked one.": "{p}: El Rey dice que puedes abrir los cofres de la tesorería. La Llave de Rubí está en el que tiene candado.",
  "{p}: Spell its word to open the lock. Then the key opens every ruby-red chest you find.": "{p}: Escribe su palabra para abrir el candado. Luego la llave abre todos los cofres rojo rubí que encuentres.",
  "{p}: Good day! The great hall gets so dusty with all these visitors.": "{p}: ¡Buenos días! El gran salón se llena de polvo con tantos visitantes.",
  "{p}: Welcome to {p}. The King is at the far end of the hall.": "{p}: Bienvenido a {p}. El Rey está al fondo del salón.",
  "{p}: The town is just outside. Enjoy your visit!": "{p}: El pueblo está justo fuera. ¡Disfruta de tu visita!",
  "{p}: My mother rules Seravel from this throne. I’m learning to sail, so I can visit every coast!": "{p}: Mi madre gobierna Seravel desde este trono. Estoy aprendiendo a navegar para visitar todas las costas.",
  "{p}: The Sapphire Key? It’s in our treasury, of course. Ask the guard there.": "{p}: ¿La Llave de Zafiro? Está en nuestra tesorería, claro. Pregunta al guardia.",
  "{p}: Bow to Her Majesty, {p}!": "{p}: ¡Inclínate ante Su Majestad, {p}!",
  "{p}: The sun never sets on Seravel. Well… it does. But slowly.": "{p}: En Seravel nunca se pone el sol. Bueno… sí se pone. Pero despacio.",
  "{p}: These shelves hold maps of every coast and island. The seas link all the way round now!": "{p}: Estos estantes guardan mapas de todas las costas e islas. ¡Ahora los mares dan la vuelta entera!",
  "{p}: Old charts say the Emerald Key sank with a ship near an island in the south-east.": "{p}: Las cartas antiguas dicen que la Llave de Esmeralda se hundió con un barco cerca de una isla del sureste.",
  "{p}: I am copying a map of the Sunken Archive. One wrong line and someone gets lost!": "{p}: Estoy copiando un mapa del Archivo Hundido. ¡Una línea mal y alguien se pierde!",
  "{p}: Spiced rice, date cakes and mint tea. Palace food is the best in the desert!": "{p}: Arroz con especias, pasteles de dátil y té de menta. ¡La comida del palacio es la mejor del desierto!",
  "{p}: Try not to steal from the townsfolk. The jail food is terrible, I hear.": "{p}: No robes a la gente del pueblo. Dicen que la comida de la cárcel es horrible.",
  "{p}: Fresh oranges from the oasis! The Queen loves them.": "{p}: ¡Naranjas frescas del oasis! A la Reina le encantan.",
  "{p}: Sand in my boots again. Sand everywhere!": "{p}: Otra vez arena en las botas. ¡Arena por todas partes!",
  "{p}: My guards watch the market. Pickpockets end up in the town jail.": "{p}: Mis guardias vigilan el mercado. Los carteristas acaban en la cárcel del pueblo.",
  "{p}: Pay the fine, or work it off with honest words. Your choice.": "{p}: Paga la multa o trabájala con palabras honradas. Tú eliges.",
  "{p}: A ruby chest, a sapphire chest, an emerald chest… a key for each color. Once you have a key, it’s yours for good.": "{p}: Un cofre de rubí, uno de zafiro, uno de esmeralda… una llave para cada color. Cuando tienes una llave, es tuya para siempre.",
  "{p}: I saw a blue sapphire chest in the desert once. Maybe you’ll find it!": "{p}: Una vez vi un cofre azul zafiro en el desierto. ¡Quizá lo encuentres!",
  "{p}: The Princess wants her blue silk ready for the feast.": "{p}: La Princesa quiere su seda azul lista para el banquete.",
  "{p}: The dining hall is ready for the ambassadors from Aldermere.": "{p}: El comedor está listo para los embajadores de Aldermere.",
  "{p}: Every ship that sails the Royal dock brings news from across the sea.": "{p}: Cada barco que zarpa del muelle real trae noticias del otro lado del mar.",
  "{p}: I bring greetings from {p}. What a beautiful palace!": "{p}: Traigo saludos de {p}. ¡Qué palacio tan bonito!",
  "{p}: The Queen allows you into the treasury. The Sapphire Key is in the word-locked chest.": "{p}: La Reina te deja entrar en la tesorería. La Llave de Zafiro está en el cofre con candado de palabras.",
  "{p}: Spell its word, and every sapphire-blue chest in the world will open for you.": "{p}: Escribe su palabra y todos los cofres azul zafiro del mundo se abrirán para ti.",
  "{p}: Mind the carpet, it’s freshly brushed!": "{p}: ¡Cuidado con la alfombra, está recién cepillada!",
  "{p}: Welcome to {p}. Her Majesty is at the end of the hall.": "{p}: Bienvenido a {p}. Su Majestad está al fondo del salón.",
  "{p}: {p} is right outside. Ships leave from the Royal dock.": "{p}: {p} está justo fuera. Los barcos salen del muelle real.",
  "{p}: I only borrowed a loaf of bread! Honest!": "{p}: ¡Solo tomé prestada una barra de pan! ¡De verdad!",
  "{p}: Forty years I picked pockets. Then I picked the Captain’s. Big mistake.": "{p}: Cuarenta años robando carteras. Luego robé la del Capitán. Gran error.",
  "{p}: Keep your hands in your own pockets and you’ll never see the inside of a cell.": "{p}: Mantén las manos en tus bolsillos y nunca verás una celda por dentro.",
  "The roads north and south of the old kingdoms are open again. Strange lands out there!": "Los caminos al norte y al sur de los viejos reinos vuelven a estar abiertos. ¡Tierras extrañas ahí fuera!",
  "Some treasures are hidden in plain sight. Walk where nobody walks.": "Algunos tesoros están escondidos a la vista. Camina por donde nadie camina.",
  "The whole continent is ringed by sea. With a ship you can reach every coast.": "Todo el continente está rodeado de mar. Con un barco puedes llegar a todas las costas.",
  "Island shrines! Sail up close and pray from your boat.": "¡Santuarios en las islas! Acércate navegando y reza desde el barco.",
  "Watch your purse in the market! There are pickpockets about.": "¡Cuidado con la bolsa en el mercado! Hay carteristas.",
  "Every town has a jail now. Thieves get a night behind bars.": "Ahora cada pueblo tiene cárcel. Los ladrones pasan una noche entre rejas.",
  "Have you seen the colored chests? Ruby, sapphire, emerald… each wants its own key.": "¿Has visto los cofres de colores? Rubí, zafiro, esmeralda… cada uno quiere su propia llave.",
  "A smooth, frosted pebble of glass. Worth {n} gold at any shop.": "Un guijarro de vidrio liso y esmerilado. Vale {n} de oro en cualquier tienda.",
  "Hold it to your ear and hear the sea. Worth {n} gold.": "Acércala al oído y oirás el mar. Vale {n} de oro.",
  "A sailor’s ring, a little tarnished. Worth {n} gold.": "Un anillo de marinero, algo ennegrecido. Vale {n} de oro.",
  "A perfect round pearl. Worth {n} gold.": "Una perla redonda y perfecta. Vale {n} de oro.",
  "A tiny statue carved from red coral. Worth {n} gold.": "Una estatuilla tallada en coral rojo. Vale {n} de oro.",
  "A pouch of old pirate coins. Worth {n} gold.": "Una bolsa de viejas monedas piratas. Vale {n} de oro.",
  "A crown from a kingdom lost to the sea. Worth {n} gold.": "Una corona de un reino que se tragó el mar. Vale {n} de oro.",
  "A deep blue gem with a star inside. Worth {n} gold.": "Una gema azul oscuro con una estrella dentro. Vale {n} de oro.",
  "Snow and fallen rock block the way.": "La nieve y las rocas caídas bloquean el paso.",
  "{p} may know how to open the old roads north and south.": "Quizá {p} sepa cómo abrir los caminos antiguos del norte y del sur.",
  "Thick black fog hangs over the sea to the north.": "Una niebla negra y espesa cubre el mar del norte.",
  "{p} may know what lies beyond it.": "Quizá {p} sepa qué hay más allá.",
  "A wall of storms blocks the southern sea.": "Un muro de tormentas bloquea el mar del sur.",
  "Black gates as tall as trees. Three empty sockets glow faintly in the stone:": "Puertas negras altas como árboles. Tres huecos vacíos brillan débilmente en la piedra:",
  "a quill, an inkwell and a star. Without all three keys, the castle will not open.": "una pluma, un tintero y una estrella. Sin las tres llaves, el castillo no se abrirá.",
  "Storms block the open sea.": "Las tormentas bloquean el mar abierto.",
  "{p} may know when the old sea lanes open.": "Quizá {p} sepa cuándo se abrirán las viejas rutas marítimas.",
  "You found something!": "¡Encontraste algo!",
  "🔑 You got the <b>{p}</b>! 🔴": "🔑 ¡Recibiste la <b>{p}</b>! 🔴",
  "🔑 You got the <b>{p}</b>! 🔵": "🔑 ¡Recibiste la <b>{p}</b>! 🔵",
  "🔑 You got the <b>{p}</b>! 🟢": "🔑 ¡Recibiste la <b>{p}</b>! 🟢",
  "It opens every ruby chest in the world, and it stays with you for good.": "Abre todos los cofres de rubí del mundo y se queda contigo para siempre.",
  "It opens every sapphire chest in the world, and it stays with you for good.": "Abre todos los cofres de zafiro del mundo y se queda contigo para siempre.",
  "It opens every emerald chest in the world, and it stays with you for good.": "Abre todos los cofres de esmeralda del mundo y se queda contigo para siempre.",
  "🔴 A ruby chest! Its keyhole is shaped like a ruby.": "🔴 ¡Un cofre de rubí! Su cerradura tiene forma de rubí.",
  "🔵 A sapphire chest! Its keyhole is shaped like a sapphire.": "🔵 ¡Un cofre de zafiro! Su cerradura tiene forma de zafiro.",
  "🟢 A emerald chest! Its keyhole is shaped like a emerald.": "🟢 ¡Un cofre de esmeralda! Su cerradura tiene forma de esmeralda.",
  "It only opens with the <b>{p}</b>.": "Solo se abre con la <b>{p}</b>.",
  "The {p} is kept in the treasury of {p}.": "La {p} se guarda en la tesorería de {p}.",
  "The {p} is kept in the treasury of {p}, in {p}.": "La {p} se guarda en la tesorería de {p}, en {p}.",
  "Old charts say the {p} lies on a far island in the south-east sea.": "Las cartas antiguas dicen que la {p} está en una isla lejana del mar del sureste.",
  "🔑 The {p} turns with a click… 🔴": "🔑 La {p} gira con un clic… 🔴",
  "🔑 The {p} turns with a click… 🔵": "🔑 La {p} gira con un clic… 🔵",
  "🔑 The {p} turns with a click… 🟢": "🔑 La {p} gira con un clic… 🟢",
  "🚨 A guard makes you pay {n} gold back. Behave yourself!": "🚨 Un guardia te hace devolver {n} de oro. ¡Pórtate bien!",
  "🔒 Clang! The cell door slams shut behind you.": "🔒 ¡Clang! La puerta de la celda se cierra de golpe detrás de ti.",
  "Talk to the {p} through the bars to get out.": "Habla con el {p} a través de los barrotes para salir.",
  "You pay {n} gold.": "Pagas {n} de oro.",
  "🔓 Clank! The cell door swings open.": "🔓 ¡Clanc! La puerta de la celda se abre.",
  "{p}: Off you go. And stay out of other folks’ pockets!": "{p}: Ya puedes irte. ¡Y no metas la mano en bolsillos ajenos!",
  "{p}: Visiting? Keep your hands in your own pockets and you’ll never stay here.": "{p}: ¿De visita? Mantén las manos en tus bolsillos y nunca te quedarás aquí.",
  "👮 {p}: “Caught with your hand in a pocket, eh?” · 💰 {n}": "👮 {p}: “Te pillaron con la mano en un bolsillo, ¿eh?” · 💰 {n}",
  "💰 Pay the fine ({n} gold)": "💰 Pagar la multa ({n} de oro)",
  "🧽 Scrub the floors (answer {n} words right)": "🧽 Fregar el suelo (acierta {n} palabras)",
  "Honest work, honest words.": "Trabajo honrado, palabras honradas.",
  "⏳ Wait": "⏳ Esperar",
  "You sit on the cold stone floor. Nobody comes to let you out.": "Te sientas en el frío suelo de piedra. Nadie viene a sacarte.",
  "✨ The floors are sparkling!": "✨ ¡El suelo reluce!",
  "{p}: Not bad. Not bad at all.": "{p}: Nada mal. Nada mal.",
  "🧽 Scrubbing the floor… {n}/{n}": "🧽 Fregando el suelo… {n}/{n}",
  "{p}: Missed a spot! Keep going.": "{p}: ¡Te dejaste una mancha! Sigue.",
  "💬 Talk": "💬 Hablar",
  "🤏 Pick their pocket": "🤏 Robarle el bolsillo",
  "They’re watching you now.": "Ahora te vigila.",
  "Their pockets are empty now.": "Ya no le queda nada en los bolsillos.",
  "A guard is watching! Move away first.": "¡Un guardia te está mirando! Aléjate primero.",
  "Listen for the word and pick it. Wrong means jail!": "Escucha la palabra y elígela. ¡Si fallas, a la cárcel!",
  "🤏 Sneaky… which word do you hear?": "🤏 Con sigilo… ¿qué palabra oyes?",
  "{p}: “Hey! THIEF!”": "{p}: “¡Eh! ¡LADRÓN!”",
  "🚨 A town guard grabs you by the collar!": "🚨 ¡Un guardia del pueblo te agarra del cuello!",
  "Off to the jail you go…": "A la cárcel…",
  "🤫 Your fingers slip into their pocket…": "🤫 Tus dedos se cuelan en su bolsillo…",
  "💰 <b>{n} gold</b>! {p} didn’t notice a thing.": "💰 ¡<b>{n} de oro</b>! {p} no se dio cuenta de nada.",
  "{p} {p} ×{n} · {n} gold each": "{p} {p} ×{n} · {n} de oro cada uno",
  "Sells one. All {n} are worth {n} gold.": "Vende uno. Los {n} valen {n} de oro.",
  "You sold the {p} for 💰 {n} gold.": "Vendiste {p} por 💰 {n} de oro.",
  "💰 Sell treasures · you have 💰 {n} gold": "💰 Vender tesoros · tienes 💰 {n} de oro",
  "💰 Sell everything ({n} gold)": "💰 Venderlo todo ({n} de oro)",
  "Sold! 💰 +{n} gold.": "¡Vendido! 💰 +{n} de oro.",
  "💰 Sell treasures": "💰 Vender tesoros",
});
GT_BOOKS.es.suffix.push(...[[" · Jail"," · Cárcel"],[" · 1F"," · P1"],[" · 2F"," · P2"]]);
