Object.assign(GT_BOOKS.es.lines, { 'Your deck’s language. Menus, battles and the story in it. Names stay the same.': 'El idioma de tu mazo. Menús, combates e historia en ese idioma. Los nombres no cambian.', 'Menus, battles and the story in this language. Your cards stay as they are.': 'Menús, combates e historia en este idioma. Tus tarjetas no cambian.' });
